CREATE OR ALTER PROCEDURE dbo.[Select_UsersMembers_Filter] @Type Int = NULL, @Employee_Number Int = NULL, @Brand_ID Int = NULL, @Branch_ID Int = NULL, @JobTitle_ID Int = NULL, @Shif_ID Int = NULL, @Gender Int = NULL, @Nationality Int = NULL
AS
BEGIN
SET NOCOUNT ON;
SELECT t.[ID], t.[Type], t.[Employee_Number], t.[FullName_Ar], t.[Fullname_En], t.[User_Image], t.[PhoneNumber], t.[MobileNumber], t.[Email], t.[Brand_ID], t.[Branch_ID], t.[Department_ID], t.[JobTitle_ID], t.[Shif_ID], t.[Gender], t.[Nationality], t.[UserName], t.[Password], t.[Status], t.[Item_Order], t.[AddedUser], t.[AddedDate], t.[ModifyUser], t.[ModifyDate], t.[IsDeleted], t.[IsActive] FROM dbo.[UsersMembers] t  WHERE ISNULL(t.IsDeleted,0)=0 AND (@Type IS NULL OR t.[Type]=@Type) AND (@Employee_Number IS NULL OR t.[Employee_Number]=@Employee_Number) AND (@Brand_ID IS NULL OR t.[Brand_ID]=@Brand_ID) AND (@Branch_ID IS NULL OR t.[Branch_ID]=@Branch_ID) AND (@JobTitle_ID IS NULL OR t.[JobTitle_ID]=@JobTitle_ID) AND (@Shif_ID IS NULL OR t.[Shif_ID]=@Shif_ID) AND (@Gender IS NULL OR t.[Gender]=@Gender) AND (@Nationality IS NULL OR t.[Nationality]=@Nationality);
END
GO
